<?php
declare(strict_types=1);
namespace OnionServiceDiscovery\Http;
use OnionServiceDiscovery\Domain\CategoryId;
use OnionServiceDiscovery\Domain\LanguageTag;
use OnionServiceDiscovery\Domain\OnionAddress;
use OnionServiceDiscovery\Protocol\ProtocolException;
use OnionServiceDiscovery\Protocol\RecordVerifier;
use OnionServiceDiscovery\Search\LocalSearch;
use OnionServiceDiscovery\Search\SearchIndex;
use OnionServiceDiscovery\Search\UnicodeSearch;
use OnionServiceDiscovery\Storage\PublicBlobStore;
use OnionServiceDiscovery\Storage\StorageBackend;

/** Explicit read-only POST profile. No transport, signer or maintenance dependency.
 * @phpstan-import-type ServiceRow from LocalSearch
 */
final readonly class ServerSearch
{
    public const FORM = '/onion-service-discovery/search/';
    public const POST = '/onion-service-discovery/search/server';
    public const STYLE = '/onion-service-discovery/search/server.css';
    public const MAX_BODY = 8192;
    public const MAX_RESULTS = 50;
    public const WALL_BUDGET_NS = 500000000;
    public function __construct(private StorageBackend $store, private PublicBlobStore $blobs, private RecordVerifier $verifier) {}
    /** @return array{query:string,language:string,category:string,adult:string} */
    public static function parse(string $type, string $body): array
    {
        if (preg_match('/\Aapplication\/x-www-form-urlencoded(?:;\s*charset=utf-8)?\z/iD', $type) !== 1 || strlen($body) > self::MAX_BODY) { throw new ProtocolException('SEARCH_REQUEST_INVALID'); }
        $values = []; $parts = explode('&', $body);
        if (count($parts) > 4) { throw new ProtocolException('SEARCH_REQUEST_INVALID'); }
        foreach ($parts as $part) {
            if (!str_contains($part, '=') || preg_match('/%(?![0-9a-fA-F]{2})/', $part) === 1) { throw new ProtocolException('SEARCH_REQUEST_INVALID'); }
            [$key, $value] = explode('=', $part, 2);
            $key = rawurldecode(str_replace('+', ' ', $key)); $value = rawurldecode(str_replace('+', ' ', $value));
            if (!in_array($key, ['query','language','category','adult'], true) || isset($values[$key]) || strlen($value) > 1024 || preg_match('//u', $value) !== 1 || preg_match('/[\x00-\x08\x0b\x0e-\x1f\x7f]/', $value) === 1) { throw new ProtocolException('SEARCH_REQUEST_INVALID'); }
            $values[$key] = $value;
        }
        if (!isset($values['query'])) { throw new ProtocolException('SEARCH_REQUEST_INVALID'); }
        $values += ['language' => '', 'category' => '', 'adult' => 'show'];
        if (strlen((string)iconv('UTF-8', 'UTF-16BE', $values['query'])) > 512 || !in_array($values['adult'], ['show','hide','de-emphasize'], true)) { throw new ProtocolException('SEARCH_REQUEST_INVALID'); }
        if ($values['language'] !== '') { LanguageTag::parse($values['language']); }
        if ($values['category'] !== '' && CategoryId::tryFrom($values['category']) === null) { throw new ProtocolException('SEARCH_REQUEST_INVALID'); }
        return ['query' => $values['query'], 'language' => $values['language'], 'category' => $values['category'], 'adult' => $values['adult']];
    }
    /** @return array{status:int,headers:array<string,string>,body:string} */
    public function search(string $method, string $type, string $body, int $started): array
    {
        if ($method !== 'POST') { return self::page(405, '<p>Submit the search form using POST. No query is accepted in a URL.</p>', ['Allow' => 'POST']); }
        if (preg_match('/\Aapplication\/x-www-form-urlencoded(?:;\s*charset=utf-8)?\z/iD', $type) !== 1) { return self::page(415, '<p>Use the plain HTML form with the supported form media type.</p>'); }
        try { $request = self::parse($type, $body); }
        catch (\InvalidArgumentException) { return self::page(strlen($body) > self::MAX_BODY ? 413 : 400, '<p>The search request was rejected. Use the bounded plain HTML form below.</p>'); }
        $budget = static function () use ($started): void { if (hrtime(true) - $started > self::WALL_BUDGET_NS) { throw new ProtocolException('SEARCH_WORK_BUDGET_EXHAUSTED'); } };
        try {
            $index = SearchIndex::load($this->store, $this->blobs, $this->verifier, $budget);
            $rows = LocalSearch::filter($index['rows'], $request['query'], $request['language'], $request['category'], $request['adult'], $budget);
            $html = '<h2>Results generated by this Node from its local published index</h2><p>Your browser has not independently verified these results. Names and descriptions are Service-declared metadata. Signatures describe key continuity; they do not establish who operates a Service.</p>';
            $html .= '<p>An empty or filtered result does not prove that a Service does not exist. This local index may be incomplete or stale.</p><p>Published index time (Node claim): ' . self::escape($index['created_at']) . '. This does not confirm current host presence.</p><p>Checkpoint: <code>' . self::escape($index['checkpoint_hash']) . '</code></p><p>' . count($rows) . ' matching identities. Showing at most ' . self::MAX_RESULTS . '. Withdrawal states are excluded; signed forks remain visible.</p><ol>';
            foreach (array_slice($rows, 0, self::MAX_RESULTS) as $row) { $budget(); $html .= self::result($row); }
            $html .= '</ol>'; $budget(); return self::page(200, $html);
        } catch (\Throwable) { return self::page(503, '<p>Server search is unavailable for this published index or its work budget. No partial result is presented. Use a local-search client or retry later.</p>'); }
    }
    /** @param ServiceRow $row */
    private static function result(array $row): string
    {
        $excerpt = UnicodeSearch::text(array_slice(UnicodeSearch::points($row['description']), 0, 240));
        $html = '<li><article><h3><bdi>' . self::escape($row['name'] === '' ? 'Unnamed service' : $row['name']) . '</bdi></h3><p><bdi>' . self::escape($excerpt) . '</bdi></p>';
        if (preg_match('/[\x{061c}\x{200e}\x{200f}\x{202a}-\x{202e}\x{2066}-\x{2069}]/u', $row['name'] . $row['description']) === 1) { $html .= '<p>Metadata contains direction-changing characters. Compare the full Onion address and identity key.</p>'; }
        if ($row['onion'] !== null) { $html .= '<p class="onion">' . self::escape($row['onion']) . '</p>'; }
        $html .= '<p>Categories: ' . self::escape(implode(', ', $row['categories'])) . ' · Languages: ' . self::escape(implode(', ', $row['languages'])) . '</p><p>Identity: <code>' . self::escape($row['genesisKey']) . '</code></p><p>' . $row['rotationCount'] . ' key-rotation proofs · ' . $row['migrationCount'] . ' migration proofs.</p>';
        if ($row['addressConflict']) { $html .= '<p>Different Service identities claim this address. Source agreement cannot replace a pinned key.</p>'; }
        if ($row['status'] === 'FORKED') { $html .= '<p>Signed fork evidence is retained. No current manifest or visit link is selected.</p>'; }
        else {
            $html .= '<p>Node-validated Service-key signature · revision ' . $row['revision'] . '. ' . $row['observationClaims'] . ' signed Node statements are claims, not independent proof. Host presence is not confirmed by this search.</p>';
            if ($row['onion'] !== null) { $onion = OnionAddress::parse($row['onion']); $html .= '<p><a rel="noopener noreferrer" href="http://' . self::escape($onion->hostname) . '/">Visit Onion Service</a></p>'; }
        }
        return $html . '</article></li>';
    }
    private static function escape(string $text): string { return htmlspecialchars($text, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
    /** @param array<string,string> $extra
     * @return array{status:int,headers:array<string,string>,body:string}
     */
    public static function page(int $status = 200, string $content = '', array $extra = [], bool $formEnabled = true): array
    {
        $categories = '<option value="">All categories</option>';
        foreach (CategoryId::cases() as $category) { $categories .= '<option value="' . self::escape($category->value) . '">' . self::escape($category->value) . '</option>'; }
        $body = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Onion Service Discovery — Server search</title><link rel="stylesheet" href="' . self::STYLE . '"></head><body><main><h1>Server search</h1>';
        $body .= '<p>Development preview — no Production Stable release or independent review is approved.</p><p class="notice">Server-side search: your search terms are sent to this Onion Service Discovery Node. The local-search privacy property does not apply in this mode.</p><p>No account, cookie or JavaScript is required. The reference application does not log or persist queries and makes no query-dependent outbound requests. The serving operator controls this page and its deployment.</p>';
        if ($formEnabled) {
        $body .= '<form method="post" action="' . self::POST . '" role="search"><label for="query">Search names, descriptions, addresses or categories</label><input id="query" name="query" type="search" maxlength="256" autocomplete="off" spellcheck="false"><label for="language">Language (optional lowercase tag, for example en)</label><input id="language" name="language" maxlength="35" autocomplete="off" spellcheck="false"><label for="category">Operator-declared category</label><select id="category" name="category">' . $categories . '</select><label for="adult">Adult category display</label><select id="adult" name="adult"><option value="show">Show</option><option value="de-emphasize">De-emphasize</option><option value="hide">Hide</option></select><button type="submit">Search on this Node</button></form>';
        }
        $body .= $content . '<p>Search semantics: version 1, frozen Unicode 17. Display grouping and category counts never grant trust or ranking advantage. Refine the query if results exceed the finite display limit.</p></main></body></html>';
        if (strlen($body) > 262144) { throw new ProtocolException('RESPONSE_TOO_LARGE'); }
        return ['status' => $status, 'headers' => $extra + ['Content-Type' => 'text/html; charset=utf-8', 'Content-Length' => (string)strlen($body), 'Cache-Control' => 'no-store', 'Referrer-Policy' => 'no-referrer', 'X-Content-Type-Options' => 'nosniff', 'X-Frame-Options' => 'DENY', 'Content-Security-Policy' => "default-src 'none'; style-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'", 'Permissions-Policy' => 'camera=(), microphone=(), geolocation=()'], 'body' => $body];
    }
    /** @return array{status:int,headers:array<string,string>,body:string} */
    public static function style(): array
    {
        $body = 'body{max-width:64rem;margin:auto;padding:1rem;font:1rem/1.55 system-ui,sans-serif;color:#17212b;background:#fff}h1,h2,h3{line-height:1.3}label{display:block;margin-top:1rem;font-weight:600}input,select,button{font:inherit;padding:.5rem;max-width:100%;box-sizing:border-box}input{width:100%}button{display:block;margin-top:1rem}a{color:#174d94}a:focus-visible,input:focus-visible,select:focus-visible,button:focus-visible{outline:3px solid #6940b6;outline-offset:3px}.notice{padding:1rem;border:2px solid #6940b6}code,.onion{overflow-wrap:anywhere}li{margin:1.5rem 0}';
        return ['status' => 200, 'headers' => ['Content-Type' => 'text/css; charset=utf-8', 'Content-Length' => (string)strlen($body), 'Cache-Control' => 'no-store', 'X-Content-Type-Options' => 'nosniff'], 'body' => $body];
    }
}
